// Why: `constructor(private readonly celsius: number) {}` declares and assigns the field
// in one go. A getter with no setter is read-only to callers.
// Docs: https://www.typescriptlang.org/docs/handbook/2/classes.html
// Test driver: don't change.
function check(celsius: number): [number, string] {
  const t = new Temperature(celsius);
  return [t.fahrenheit, t.describe()];
}

class Temperature {
  constructor(private readonly celsius: number) {}

  get fahrenheit(): number {
    return (this.celsius * 9) / 5 + 32;
  }

  describe(): string {
    return `${this.celsius}°C`;
  }
}

